EXTRA4.src="Soru numaraları ve sayıları ÖSYM'nin YDS/e-YDS formatına göredir (80 soru, 180 dakika). Kaynak: sinavtime.com ve rehberpanda.com YDS soru dağılımı tabloları, uygulamadaki geçmiş sınav cevap kâğıtlarıyla karşılaştırıldı.";

const _st=(arr)=>`<ol class="steps">${arr.map(a=>`<li><b>${a[0]}</b><span>${a[1]}</span></li>`).join("")}</ol>`;
const _trap=(arr)=>`<div class="sbox rd"><b>Sık yapılan hatalar</b><ul>${arr.map(a=>`<li>${a}</li>`).join("")}</ul></div>`;
const _ex=(q,opts,a,why)=>`<div class="card exq"><p class="small mut" style="margin:0">Çözümlü örnek</p><p class="gsent" style="font-size:17px">${q}</p><ol type="A">${opts.map((o,i)=>`<li${i===a?' class="okopt"':""}>${o}</li>`).join("")}</ol><p class="small"><b>Çözüm:</b> ${why}</p></div>`;
const _time=(t)=>`<p class="chip k">Önerilen süre: ${t}</p>`;

