  const tbl=rows.map(r=>`<h3>${gname[r.g]} · ${r.it.length} fiil</h3><div class="tblwrap"><table class="tbl irr"><tr><th>V1</th><th>V2</th><th>V3</th><th>Türkçe</th></tr>${r.it.map(v=>`<tr><td><b>${v.v1}</b></td><td>${v.v2}</td><td>${v.v3}</td><td>${v.t}</td></tr>`).join("")}</table></div>`).join("");
